public final class Order {                     // no framework imports
    private final CustomerId customerId;
    private final List<Line> lines = new ArrayList<>();
    private Money total = Money.ZERO;

    public static Order open(CustomerId c) { return new Order(c); }

    public void addLine(Line l) {              // invariant checked here
        Money next = total.plus(l.price());
        if (next.isGreaterThan(LIMIT)) throw new OrderLimitExceeded(customerId);
        lines.add(l);
        total = next;
    }
}
